Q: Why Link doesnt work with styling after passing it as a prop? A: <p>Could you include what exactly makes up the <code>Link</code> component?</p>
<p>But the solution to this might be to actually have <code>className</code> as a <code>Link</code> component prop and then u pass that into the actual html element being returned. An example is below;</p>
<pre class="lang-jsx prettyprint-override"><code>function Link({className, children, to}) {
    return &lt;a className={className} href={to}&gt;{children}&lt;/a&gt;
}
</code></pre>
<p>Also just keep this</p>
<pre><code>.link:active{
    text-decoration: underline;
}
</code></pre>
<p>without the</p>
<pre><code>text-decoration: none;
</code></pre>
<p>or you can do</p>
<pre><code>.link {
    text-decoration: none;
}
</code></pre>
<p>PS:// Please correct me for any mistakes or reply if this helps</p>

Q: Add gap to the keyboard toolbar A: <p><a href="https://i.sstatic.net/MBOTRlZp.png" rel="nofollow noreferrer">Screenshot DARK</a></p>
<p><a href="https://i.sstatic.net/fzAKjjS6.png" rel="nofollow noreferrer">Screenshot LIGHT</a></p>
<pre><code>import SwiftUI

struct ContentView: View {
    @FocusState private var focusedField: Field?
    @State private var text1 = &quot;&quot;
    @State private var text2 = &quot;&quot;
    @State private var text3 = &quot;&quot;

    enum Field: Hashable {
        case field1, field2, field3
    }

    private let fieldOrder: [Field] = [.field1, .field2, .field3]

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    TextField(&quot;Field 1&quot;, text: $text1)
                        .focused($focusedField, equals: .field1)

                    TextField(&quot;Field 2&quot;, text: $text2)
                        .focused($focusedField, equals: .field2)

                    TextField(&quot;Field 3&quot;, text: $text3)
                        .focused($focusedField, equals: .field3)
                }
            }
            .safeAreaInset(edge: .bottom) {
                if focusedField != nil {
                    buildKeyboardToolbar(
                        current: focusedField,
                        ordered: fieldOrder,
                        set: { focusedField = $0 }
                    )
                }
            }
        }
    }
}

struct ToolbarIconButton: View {
    let systemImage: String
    let isActive: Bool
    let action: () -&gt; Void

    var body: some View {
        Button {
            action()
        } label: {
            Image(systemName: systemImage)
                .font(.title2)
                .frame(width: 50, height: 50)
        }
        .foregroundStyle(isActive ? .primary: .quaternary)
        .contentShape(Rectangle())
        .disabled(!isActive)
    }
}

struct KeyboardToolbarView: View {
    var showArrows: Bool = false
    var canMoveUp: Bool = false
    var canMoveDown: Bool = false
    var moveUp: () -&gt; Void = {}
    var moveDown: () -&gt; Void = {}
    var done: () -&gt; Void

    var body: some View {
        HStack(spacing: 5) {
            if showArrows {
                ToolbarIconButton(
                    systemImage: &quot;chevron.up&quot;,
                    isActive: canMoveUp,
                    action: moveUp
                )

                ToolbarIconButton(
                    systemImage: &quot;chevron.down&quot;,
                    isActive: canMoveDown,
                    action: moveDown
                )
            }

            ToolbarIconButton(
                systemImage: &quot;checkmark&quot;,
                isActive: true,
                action: done
            )
            .frame(maxWidth: .infinity, alignment: .trailing)
        }
        .glassEffect(.regular.interactive())
        .padding(.horizontal)
        .padding(.bottom, 10)
    }
}

func moveFocus&lt;T: Equatable&gt;(
    direction: FocusDirection,
    current: T?,
    ordered: [T],
    setter: (T?) -&gt; Void
) {
    guard let current,
          let index = ordered.firstIndex(of: current) else { return }

    switch direction {
    case .up:
        if index &gt; 0 {
            setter(ordered[index - 1])
        }
    case .down:
        if index &lt; ordered.count - 1 {
            setter(ordered[index + 1])
        } else {
            setter(nil)
        }
    }
}

func canMoveFocus&lt;T: Equatable&gt;(
    direction: FocusDirection,
    current: T?,
    ordered: [T]
) -&gt; Bool {
    guard let current,
          let index = ordered.firstIndex(of: current) else { return false }

    switch direction {
    case .up: return index &gt; 0
    case .down: return index &lt; ordered.count - 1
    }
}

func buildKeyboardToolbar&lt;T: Equatable&gt;(
    current: T?,
    ordered: [T],
    set: @escaping (T?) -&gt; Void
) -&gt; KeyboardToolbarView {
    KeyboardToolbarView(
        showArrows: current != nil,
        canMoveUp: canMoveFocus(
            direction: .up,
            current: current,
            ordered: ordered
        ),
        canMoveDown: canMoveFocus(
            direction: .down,
            current: current,
            ordered: ordered
        ),
        moveUp: {
            moveFocus(direction: .up, current: current, ordered: ordered) {
                set($0)
            }
        },
        moveDown: {
            moveFocus(direction: .down, current: current, ordered: ordered) {
                set($0)
            }
        },
        done: {
            set(nil)
        }
    )
}

enum FocusDirection {
    case up, down
}

#Preview {
    ContentView()
}
</code></pre>
